/// Return a borrowed UTF-8 prefix within the requested byte budget.
pub fn bounded_prefix(input: &str, max_bytes: usize) -> &str {
    let end = input.char_indices().nth(max_bytes).map_or(input.len(), |(index, _)| index);
    &input[..end]
}

/// Return a borrowed UTF-8 prefix within the requested byte budget.
pub fn bounded_prefix(input: &str, max_bytes: usize) -> &str {
    let mut end = input.len().min(max_bytes);
    while !input.is_char_boundary(end) {
        end -= 1;
    }
    &input[..end]
}

